def bmi(weight_kg, height_m):
    """Повертає кортеж (bmi, категорія) за заданою вагою та ростом."""
    bmi_value = weight_kg / (height_m ** 2)

    if bmi_value < 18.5:
        category = 'underweight'
    elif bmi_value < 25:
        category = 'normal'
    elif bmi_value < 30:
        category = 'overweight'
    else:
        category = 'obese'

    return bmi_value, category
